impl Solution {
    pub fn k_items_with_maximum_sum(num_ones: i32, num_zeros: i32, num_neg_ones: i32, k: i32) -> i32 {
        let mut sum = 0;
        let mut remaining = k;

        // First, take all the 1s
        let ones_taken = num_ones.min(remaining);
        sum += ones_taken;
        remaining -= ones_taken;

        // If we still need more items, take 0s
        let zeros_taken = num_zeros.min(remaining);
        remaining -= zeros_taken;

        // If we still need more items, take -1s
        let neg_ones_taken = num_neg_ones.min(remaining);
        sum -= neg_ones_taken;

        sum
    }
}

